            'u_count', 'u_roughness', 'u_fiber', 'u_proportion', 'u_octaveCount', 'u_persistence', 'u_lacunarity', 'u_glow', 'u_gap', 'u_colorSteps', 'u_originalColors', 'u_inverted', 'u_grid',
